void AAmberHUD::SetLayer(FName Tag,bool Visible){LayerState.Add(Tag,Visible);if(Tag=="TiltShift"){for(TActorIterator<AActor> It(GetWorld());It;++It){TArray<UCameraComponent*> Cs;It->GetComponents(Cs);for(auto C:Cs)for(auto& B:C->PostProcessSettings.WeightedBlendables.Array)B.Weight=Visible?1.f:0.f;}}if(Tag=="GroundCover"){for(auto Weak:Foliage)if(auto C=Weak.Get())if(C->GetStaticMesh()&&(C->GetStaticMesh()->GetName().Contains("GRASS")||C->GetStaticMesh()->GetName().Contains("CLOVER")||C->GetStaticMesh()->GetName().Contains("WATERPLANT")))C->SetVisibility(Visible);}for(TActorIterator<AActor> It(GetWorld());It;++It)if(It->ActorHasTag(Tag))It->SetActorHiddenInGame(!Visible);}
void AAmberHUD::SetDensity(float Value){Density=FMath::Clamp(Value,0.f,1.f);for(int32 i=0;i<Foliage.Num();i++)if(auto C=Foliage[i].Get()){C->ClearInstances();int32 Count=FMath::RoundToInt(FullTransforms[i].Num()*Density);TArray<FTransform> Ts;Ts.Append(FullTransforms[i].GetData(),Count);C->AddInstances(Ts,false,false);}}
void AAmberHUD::PlayTrack(const FString& Name){CurrentTrack=Name;FString Path="/Game/AbbiesWorld/Audio/UserMusic/Score_"+Name+".Score_"+Name;auto Sound=LoadObject<USoundBase>(nullptr,*Path);if(!Sound)return;for(TActorIterator<AAmbientSound> It(GetWorld());It;++It){It->GetAudioComponent()->Stop();It->GetAudioComponent()->SetSound(Sound);if(MusicOn)It->GetAudioComponent()->FadeIn(1.2f,.3f);}}
void AAmberHUD::SetMusic(bool Enabled){MusicOn=Enabled;for(TActorIterator<AAmbientSound> It(GetWorld());It;++It){if(Enabled)It->GetAudioComponent()->Play();else It->GetAudioComponent()->Stop();}}
void AAmberHUD::SwitchWorld(const FString& Name){FString Map;if(Name==TEXT("Papercraft"))Map=TEXT("AmberVale_Papercraft");else if(Name==TEXT("HalloweenCandyland"))Map=TEXT("AmberVale_HalloweenCandyland");else if(Name==TEXT("MoonBase"))Map=TEXT("MoonBase");else if(Name==TEXT("ChristmasVillage")||Name==TEXT("EnchantedForest"))Map=Name;else return;if(GetWorld()->GetMapName().EndsWith(Map))return;ResumeWorld=GameStarted;ResumeDeveloper=DeveloperMode;UGameplayStatics::OpenLevel(this,FName(*(TEXT("/Game/AbbiesWorld/Overland/Maps/")+Map)));}
void AAmberHUD::SwitchSkin(bool Halloween){UGameplayStatics::OpenLevel(this,FName(Halloween?TEXT("/Game/AbbiesWorld/Overland/Maps/AmberVale_HalloweenCandyland"):TEXT("/Game/AbbiesWorld/Overland/Maps/AmberVale_Papercraft")));}
void AAmberHUD::SelectAt(FVector O,FVector D){if(FMath::Abs(D.Z)<.001)return;float Best=FLT_MAX;for(auto P:Tiles){float T=(P.Z-O.Z)/D.Z;if(T<0)continue;FVector Hit=O+D*T;if(FVector::DistSquared2D(Hit,P)<190*190&&T<Best){Best=T;Selected=P;HasSelection=true;if(auto PC=Cast<AAmberController>(GetOwningPlayerController()))PC->FocusPoint(P+FVector(0,0,100));}}}
void AAmberHUD::MoveStep(){if(!DeveloperMode&&Identity&&(Identity->SavingUniverse||Identity->UniverseSaveFailed))return;if(GameStarted&&!Moving&&Step+1<Route.Num()){Moving=true;MoveTime=0;}}
void AAmberHUD::ShuffleDeer(){if(!Deer.IsValid())return;DeerFrom=Deer->GetActorLocation();TArray<FVector> Candidates;for(auto P:Tiles)if(FVector::Dist2D(P,DeerFrom)>300&&FVector::Dist2D(P,DeerFrom)<410&&FMath::Abs(P.Z-DeerFrom.Z)<310){bool Blocked=false;for(TActorIterator<AActor> It(GetWorld());It;++It)if(It->ActorHasTag("POI")&&FVector::Dist2D(P,It->GetActorLocation())<1000){Blocked=true;break;}if(!Blocked)Candidates.Add(P);}if(Candidates.Num()){DeerTo=Candidates[(Turn/5)%Candidates.Num()];DeerTime=0;DeerMoving=true;}}
void AAmberHUD::Tick(float Dt){Super::Tick(Dt);TickFrontDoor(Dt);Clock+=Dt;if(FParse::Param(FCommandLine::Get(),TEXT("BoardProof"))||(GameStarted&&FParse::Param(FCommandLine::Get(),TEXT("BoardPreview")))){static bool Captured=false,Configured=false;if(!Configured){SetDensity(.35);SetMusic(true);Configured=true;}if(FParse::Param(FCommandLine::Get(),TEXT("BoardProof"))&&Turn<5&&!Moving)MoveStep();if(Clock>35&&!Captured){if(FParse::Param(FCommandLine::Get(),TEXT("BoardProof"))){DrawerShell->SetVisibility(EVisibility::Collapsed);Scrim->SetVisibility(EVisibility::Collapsed);}FScreenshotRequest::RequestScreenshot(FPaths::ProjectDir()/(CompactWorld(GetWorld()->GetMapName())?TEXT("native-game-MoonBase.png"):GetWorld()->GetMapName().Contains("Halloween")?TEXT("native-game-Halloween.png"):TEXT("native-game-Papercraft.png")),true,false);FFileHelper::SaveStringToFile(FString::Printf(TEXT("{\"completed_moves\":%d,\"density\":%.2f,\"route_steps\":%d,\"fps_sample\":%.1f,\"scope\":\"uncooked native game preview\"}"),Turn,Density,Route.Num(),SmoothedFPS),*(FPaths::ProjectDir()/TEXT("native-game-test.json")));Captured=true;}if(Clock>40&&FParse::Param(FCommandLine::Get(),TEXT("BoardProof")))GetOwningPlayerController()->ConsoleCommand("quit");}if(!DeveloperMode&&LayerState.FindRef("EdgeLock")&&GetOwningPlayerController()->GetViewTarget()==GetOwningPlayerController()->GetPawn()){auto FlightPawn=GetOwningPlayerController()->GetPawn();FVector P=FlightPawn->GetActorLocation();float R=P.Y/330.f,Q=P.X/(FMath::Sqrt(3.f)*220.f)-R/2,N=FMath::Max3(FMath::Abs(Q),FMath::Abs(R),FMath::Abs(Q+R));if(N>39){P.X*=39/N;P.Y*=39/N;}P.Z=FMath::Clamp(P.Z,200.f,24000.f);FlightPawn->SetActorLocation(P);}SmoothedFPS=FMath::Lerp(SmoothedFPS,1/FMath::Max(Dt,.001f),.04f);auto Hex=[this](FVector P,float R,FColor Color){for(int32 k=0;k<6;k++){float A=(k+.5f)*PI/3,B=(k+1.5f)*PI/3;DrawDebugLine(GetWorld(),P+FVector(FMath::Cos(A)*R,FMath::Sin(A)*R,30),P+FVector(FMath::Cos(B)*R,FMath::Sin(B)*R,30),Color,false,0,0,3);}};if(GameStarted&&LayerState.FindRef("RouteMotion")){for(auto P:Route)Hex(P,195,FColor(255,191,76));if(Route.Num()){float F=FMath::Fmod(Clock*.55f,FMath::Max(1,Route.Num()-1));int32 I=FMath::FloorToInt(F);FVector P=FMath::Lerp(Route[I],Route[FMath::Min(I+1,Route.Num()-1)],F-I);DrawDebugSphere(GetWorld(),P+FVector(0,0,50),24,12,FColor(255,240,180),false,0,0,3);}}if(GameStarted&&HasSelection&&LayerState.FindRef("Selection"))Hex(Selected,210, FLinearColor(1,.65+.25*FMath::Sin(Clock*3),.2).ToFColor(true));if(Moving&&Token.IsValid()){MoveTime=FMath::Min(1.f,MoveTime+Dt*.8f);float E=FMath::SmoothStep(0.f,1.f,MoveTime);FVector P=FMath::Lerp(Route[Step],Route[Step+1],E)+FVector(0,0,45+75*FMath::Sin(MoveTime*PI));Token->SetActorLocation(P);Token->SetActorRotation(FRotator(0,FMath::RadiansToDegrees(FMath::Atan2((Route[Step+1]-Route[Step]).Y,(Route[Step+1]-Route[Step]).X))-90,FMath::Sin(MoveTime*2*PI)*5));if(MoveTime==1){Moving=false;Step++;Turn++;if(!DeveloperMode&&Identity)Identity->SaveUniverseProgress(Turn,Step);if(Turn%5==0)ShuffleDeer();}}if(DeerMoving&&Deer.IsValid()){DeerTime=FMath::Min(1.f,DeerTime+Dt*.6f);Deer->SetActorLocation(FMath::Lerp(DeerFrom,DeerTo,FMath::SmoothStep(0.f,1.f,DeerTime))+FVector(0,0,FMath::Sin(DeerTime*PI)*30));if(DeerTime==1)DeerMoving=false;}}
void AAmberHUD::EndPlay(const EEndPlayReason::Type Reason){CloseFrontDoor();if(GEngine&&GEngine->GameViewport&&Panel.IsValid())GEngine->GameViewport->RemoveViewportWidgetContent(Panel.ToSharedRef());Panel.Reset();Super::EndPlay(Reason);}
